effect.shader:
/** Luminância ITU-R BT.709. */
float luma(vec3 c) {
    return dot(c, vec3(0.2126, 0.7152, 0.0722));
}

/**
 * Média e variância (pela luma) de um quadrante 3×3 começando em (ox, oy)
 * do pixel central. Retorna vec4(mediaRGB, variancia).
 */
vec4 quadrante(vec2 uv, vec2 passo, int ox, int oy) {
    vec3 somaCor = vec3(0.0);
    float somaLuma = 0.0;
    float somaLumaQuadrado = 0.0;
    int n = 0;
    for (int y = 0; y < 3; y++) {
        for (int x = 0; x < 3; x++) {
            vec2 d = vec2(float(ox + x), float(oy + y)) * passo;
            vec3 c = texture(inputImg, uv + d).rgb;
            somaCor += c;
            float L = luma(c);
            somaLuma += L;
            somaLumaQuadrado += L * L;
            n++;
        }
    }
    float m = somaLuma / float(n);
    float variancia = somaLumaQuadrado / float(n) - m * m;
    vec3 mediaRGB = somaCor / float(n);
    return vec4(mediaRGB, variancia);
}

void main() {
    vec2 tam = vec2(textureSize(inputImg, 0));
    vec2 passo = radius / tam / 3.0;

    vec4 original = texture(inputImg, acScreenNorm);

    // 4 quadrantes 3×3 em volta do pixel central: TL, TR, BL, BR.
    vec4 tl = quadrante(acScreenNorm, passo, -3, -3);
    vec4 tr = quadrante(acScreenNorm, passo,  1, -3);
    vec4 bl = quadrante(acScreenNorm, passo, -3,  1);
    vec4 br = quadrante(acScreenNorm, passo,  1,  1);

    // Devolve a média do quadrante com menor variância.
    vec3 escolhido = tl.rgb;
    float menorVar = tl.a;
    if (tr.a < menorVar) { escolhido = tr.rgb; menorVar = tr.a; }
    if (bl.a < menorVar) { escolhido = bl.rgb; menorVar = bl.a; }
    if (br.a < menorVar) { escolhido = br.rgb; menorVar = br.a; }

    vec3 cor = mix(original.rgb, escolhido, strength);
    fragColor = vec4(cor, original.a);
}
